        start, end = map(int, s.split('-'))
    elif re.match(r'^\d+\-$', s):
        start, end = int(s[:-1]), None
    elif re.match(r'^\-\d+$', s):
        start, end = None, int(s[1:])
    else:
        raise ValueError("Invalid range string format")

    # Check if the start and end are valid
    if start is None and end is None:
        raise ValueError("Invalid range string format")
    if start is None:
        start = 0
    if end is None:
        end = -1

    # Clamp the end to the resource length
    if end < 0:
        end = -1
    if end > resource_length:
        end = resource_length

    # Check if the range is unsatisfiable
    if start > end:
        raise ValueError("Unsatisfiable range")

    return (start, end)"
  }
}
